SHOPPING_TOOLS = ["check_cart_before_checkout", "validate_purchase_plan", "check_compatibility", "find_parts",
                  "check_recalls", "attach_order", "report_outcome", "file_claim"]


def _pick(names=None):
    if not names:
        return TOOL_DEFINITIONS
    want = set(names)
    return [t for t in TOOL_DEFINITIONS if t["name"] in want]


def to_openai_tools(names=None):
    """OpenAI Chat Completions "tools" list."""
    return [{"type": "function", "function": {"name": t["name"], "description": t["description"],
                                               "parameters": t["input_schema"]}} for t in _pick(names)]


def to_anthropic_tools(names=None):
    """Anthropic Messages API "tools" list."""
    return [{"name": t["name"], "description": t["description"], "input_schema": t["input_schema"]} for t in _pick(names)]


def run_tool(client, name, args=None):
    """Run a tool call your model asked for. args may be a dict or a JSON string."""
    if isinstance(args, str):
        args = json.loads(args or "{}")
    return (client or TetheredTrust()).call(name, args or {})


def to_langchain_tools(client=None, names=None):
    """LangChain StructuredTools (needs langchain-core installed)."""
    from langchain_core.tools import StructuredTool  # optional dependency

    client = client or TetheredTrust()
    out = []
    for t in _pick(names):
        def _run(_name=t["name"], **kwargs):
            return json.dumps(client.call(_name, kwargs))
        out.append(StructuredTool.from_function(func=_run, name=t["name"], description=t["description"][:1024],
                                                args_schema=t["input_schema"]))
    return out
